CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY, name text NOT NULL, api_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), email text NOT NULL, name text NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), customer_id uuid NOT NULL REFERENCES customers(id), amount bigint NOT NULL CHECK(amount>0), currency char(3) NOT NULL CHECK(currency='USD'), status text NOT NULL, due_date date, line_items jsonb NOT NULL, payment_id uuid);
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), amount bigint NOT NULL CHECK(amount>0), currency char(3) NOT NULL, status text NOT NULL, provider text NOT NULL, provider_id text, idempotency_key text, request_fingerprint text NOT NULL, attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS payment_attempts (id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(id),status text NOT NULL,provider_id text,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_registrations (id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),url text NOT NULL,secret text NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id uuid PRIMARY KEY,registration_id uuid NOT NULL REFERENCES webhook_registrations(id),event_id text NOT NULL,payload jsonb NOT NULL,attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz);
